export const currencies=['EUR','USD','GBP'];
export const statuses=['submitted','approved','rejected'];
export const amount = s => Math.round(s.minutes*s.rateCents/60);
export function balance(data,projectId,excludeSessionId=null){return data.sessions.filter(s=>s.projectId===projectId&&s.status==='approved'&&s.id!==excludeSessionId).reduce((n,s)=>n+amount(s),0)-data.payouts.filter(p=>p.projectId===projectId).reduce((n,p)=>n+p.amountCents,0)}
export function totals(data,currency){const ids=new Set(data.projects.filter(p=>p.currency===currency).map(p=>p.id));const rows=data.sessions.filter(s=>ids.has(s.projectId));return {minutes:rows.reduce((n,s)=>n+s.minutes,0),submitted:rows.filter(s=>s.status==='submitted').reduce((n,s)=>n+amount(s),0),approved:rows.filter(s=>s.status==='approved').reduce((n,s)=>n+amount(s),0),paid:data.payouts.filter(p=>ids.has(p.projectId)).reduce((n,p)=>n+p.amountCents,0)}}
export function validate(data){
if(!data||data.version!==1||!['projects','sessions','payouts'].every(k=>Array.isArray(data[k])&&data[k].length<=20000))throw Error('This is not a supported Freelance Ledger backup.');
const text=(v,max=200)=>typeof v==='string'&&v.length<=max;const id=v=>text(v,100)&&/^[A-Za-z0-9_-]+$/.test(v);const money=v=>Number.isSafeInteger(v)&&v>0&&v<=100000000;const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
for(const k of ['projects','sessions','payouts'])if(new Set(data[k].map(x=>x?.id)).size!==data[k].length)throw Error('Duplicate record IDs.');
for(const p of data.projects)if(!p||!id(p.id)||!text(p.name,80)||!p.name.trim()||!text(p.platform,80)||!currencies.includes(p.currency)||!money(p.rateCents))throw Error('Invalid project data.');
const ids=new Set(data.projects.map(p=>p.id));
for(const s of data.sessions)if(!s||!id(s.id)||!ids.has(s.projectId)||!date(s.date)||!Number.isInteger(s.minutes)||s.minutes<1||s.minutes>1440||!money(s.rateCents)||!statuses.includes(s.status)||!text(s.note,500))throw Error('Invalid work session.');
for(const p of data.payouts)if(!p||!id(p.id)||!ids.has(p.projectId)||!date(p.date)||!money(p.amountCents)||!text(p.note,500))throw Error('Invalid payout.');
for(const p of data.projects)if(balance(data,p.id)<0)throw Error('A payout exceeds approved earnings.');return data;
}
export function emptyData(){return {version:1,projects:[],sessions:[],payouts:[]}}
export function demoData(){const d=emptyData();const day=n=>{const x=new Date();x.setDate(x.getDate()-n);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};d.projects=[{id:'p1',name:'AI response evaluation',platform:'Northstar Labs · demo',currency:'USD',rateCents:8000},{id:'p2',name:'Product research',platform:'Studio Field · demo',currency:'EUR',rateCents:6500},{id:'p3',name:'Coding assistant feedback',platform:'Atlas AI · demo',currency:'USD',rateCents:7000}];
d.sessions=[{id:'s1',projectId:'p1',date:day(0),minutes:150,rateCents:8000,status:'submitted',note:'Compare responses and document reasoning'},{id:'s2',projectId:'p3',date:day(1),minutes:120,rateCents:7000,status:'approved',note:'Review project setup suggestions'},{id:'s3',projectId:'p1',date:day(2),minutes:180,rateCents:8000,status:'approved',note:'Evaluate task batch 04'},{id:'s4',projectId:'p2',date:day(2),minutes:90,rateCents:6500,status:'submitted',note:'Synthesize interview themes'},{id:'s5',projectId:'p1',date:day(3),minutes:240,rateCents:8000,status:'approved',note:'Review and quality checks'},{id:'s6',projectId:'p3',date:day(4),minutes:90,rateCents:7000,status:'submitted',note:'Test a new feature workflow'},{id:'s7',projectId:'p1',date:day(5),minutes:180,rateCents:8000,status:'approved',note:'Evaluate task batch 03'},{id:'s8',projectId:'p2',date:day(6),minutes:240,rateCents:6500,status:'approved',note:'Discovery workshop preparation'},{id:'s9',projectId:'p3',date:day(6),minutes:60,rateCents:7000,status:'rejected',note:'Incomplete comparison — not accepted'}];d.payouts=[{id:'pay1',projectId:'p1',date:day(1),amountCents:40000,note:'First weekly payout'},{id:'pay2',projectId:'p2',date:day(2),amountCents:13000,note:'Partial settlement'}];return d;}
